-- PROPOSED ONLY — READ-ONLY verification after applying PROPOSED_20261012140000_intel_runtime.sql.
-- Every row must say ok = true. Selects only; safe any time.
with t as (select c.relname, c.relrowsecurity, c.relforcerowsecurity from pg_class c where c.relnamespace = 'agent'::regnamespace and c.relkind = 'r')
select 'agent tables = 21 (18 + job_event, runtime_schedule, runtime_heartbeat)' as check, (select count(*) from t) = 21 as ok, (select count(*)::text from t) as detail
union all select 'every agent table: RLS enabled + forced', (select bool_and(relrowsecurity and relforcerowsecurity) from t), (select string_agg(relname, ',') from t where not (relrowsecurity and relforcerowsecurity))
union all select 'runtime born OFF: runtime_enabled=false, emergency_stop=false', (select not runtime_enabled and not emergency_stop from agent.runtime_limits where id = 1), (select format('enabled=%s stop=%s global=%s kinds=%s', runtime_enabled, emergency_stop, max_concurrency_global, kind_limits) from agent.runtime_limits where id = 1)
union all select 'global concurrency ≤ 4 (default 2), lease 15–300 s, statement_timeout ≤ 5 s', (select max_concurrency_global <= 4 and lease_seconds between 15 and 300 and statement_timeout_ms <= 5000 from agent.runtime_limits where id = 1), null
union all select 'no schedule enabled until the owner creates one', not exists (select 1 from agent.runtime_schedule where enabled), (select count(*)::text from agent.runtime_schedule)
union all select 'research rows untouched (runtime_managed = false)', not exists (select 1 from agent.research_job where kind ~ '^research\.' and runtime_managed), null
union all select 'run-owned ledger rows intact (run_id set, job_id null)', not exists (select 1 from agent.spend_ledger where run_id is null and job_id is null), (select format('run_owned=%s job_owned=%s', count(*) filter (where run_id is not null), count(*) filter (where job_id is not null)) from agent.spend_ledger)
union all select 'research spend switch unchanged (research_limits.enabled)', true, (select enabled::text from agent.research_limits where id = 1)
union all select 'guard triggers present (research_job_runtime_guard, job_event_guard_mut, job_event_no_truncate)', (select count(*) = 3 from pg_trigger where not tgisinternal and tgname in ('research_job_runtime_guard','job_event_guard_mut','job_event_no_truncate')), null
union all select 'anon / authenticated execute no runtime function', not exists (select 1 from pg_proc p where p.pronamespace = 'agent'::regnamespace and (p.proname like 'runtime\_%' or p.proname = 'ops_health_snapshot') and (has_function_privilege('anon', p.oid, 'EXECUTE') or has_function_privilege('authenticated', p.oid, 'EXECUTE'))), null
union all select 'authenticated may execute only can_read_org', (select coalesce(string_agg(p.proname, ','), '') = 'can_read_org' from pg_proc p where p.pronamespace = 'agent'::regnamespace and has_function_privilege('authenticated', p.oid, 'EXECUTE')), null
union all select 'agent_api: runtime tables read-only', not exists (select 1 from unnest(array['agent.job_event','agent.runtime_schedule','agent.runtime_heartbeat']) tb, unnest(array['INSERT','UPDATE','DELETE','TRUNCATE']) p where has_table_privilege('agent_api', tb, p)), null
union all select 'agent_api: cannot create schedules or reach internal runtime functions', not has_function_privilege('agent_api', 'agent.runtime_upsert_schedule(text, text, integer, text, jsonb, boolean, timestamptz, numeric)', 'EXECUTE') and not has_function_privilege('agent_api', 'agent.runtime_emit(agent.research_job, text, text, jsonb)', 'EXECUTE'), null
union all select 'agent_api: still no DELETE anywhere in agent', not exists (select 1 from t where has_table_privilege('agent_api', 'agent.' || t.relname, 'DELETE')), null
union all select 'every agent SECURITY DEFINER function pins search_path', not exists (select 1 from pg_proc p where p.pronamespace = 'agent'::regnamespace and p.prosecdef and not exists (select 1 from unnest(p.proconfig) c where c like 'search_path=%')), null
union all select 'runtime indexes present (8 on research_job + schedule/job_event/spend/finding)', (select count(*) = 13 from pg_indexes where schemaname = 'agent' and indexname in ('research_job_idem_uq','research_job_schedule_slot_uq','research_job_runtime_due_idx','research_job_runtime_leased_idx','research_job_runtime_open_idx','research_job_schedule_open_idx','research_job_runtime_ended_idx','research_job_runtime_recent_idx','runtime_schedule_due_idx','job_event_job_idx','spend_ledger_job','finding_job_key_uq','finding_job_recent_idx')), null;
